    if (crashed) dock.emit({ type: "tab-crashed", payload: { identity: tab("tab-2", 2), reason: "crashed" } })
    const gate = Promise.withResolvers<void>()
    const recovered = { tabID: "tab-1", generation: 3, url: "https://example.com/a" }
