describe("MCP Dock controller with the Linux workspace", () => {
  const workspace = (tabID: string, generation: number) => ({ tabID, generation, url: "appdock://linux" as const })
  const ready = async () => {
    const dock = fakeDock()
    const controller = createAppDockController(dock.api, translate)
    controller.attach(element(), profileA)
    await until(() => controller.state.status === "ready")
    controller.setURL("https://example.com/a")
    await controller.launch()
    return { dock, controller }
  }
  const openLinux = async (
    setup: Awaited<ReturnType<typeof ready>>,
    tab: ReturnType<typeof workspace>,
    during?: () => void,
  ) => {
    const pending = setup.controller.openLinux()
    await until(() => setup.dock.linuxPending() === 1)
    during?.()
    setup.dock.resolveLinux({ status: "opened", tab })
    return pending
  }

  test("a replaced workspace view leaves one Linux tab beside the browser tabs, and is never saved", async () => {
    const setup = await ready()
    await openLinux(setup, workspace("linux-1", 10))
    await openLinux(setup, workspace("linux-2", 11))
    expect(setup.controller.state.tabs.map((item) => item.tabID)).toEqual(["tab-1", "linux-2"])
    expect(setup.controller.state.active).toEqual(tab("linux-2", 11))
    expect(setup.controller.state.mode).toBe("linux")
    await settle()
    expect(setup.dock.manifest().tabs[profileA]).toEqual([{ url: "https://example.com/a", pinned: false }])
  })

  test("a browser selection while the workspace opens keeps the browser on screen", async () => {
    const setup = await ready()
    const result = await openLinux(setup, workspace("linux-1", 10), () =>
      setup.dock.emit({ type: "tab-selected", payload: tab("tab-1", 1) }),
    )
    expect(result).toBeUndefined()
    expect(setup.controller.state.active).toEqual(tab("tab-1", 1))
    expect(setup.controller.state.mode).toBe("browser")
  })

  test("the workspace's own selection event does not cancel its reconnect", async () => {
    const setup = await ready()
    await openLinux(setup, workspace("linux-1", 10))
    const result = await openLinux(setup, workspace("linux-1", 10), () =>
      setup.dock.emit({ type: "tab-selected", payload: tab("linux-1", 10) }),
    )
    expect(result).toEqual({ status: "opened", tab: workspace("linux-1", 10) })
    expect(setup.controller.state.active).toEqual(tab("linux-1", 10))
    expect(setup.controller.state.mode).toBe("linux")
  })

  test("selection events for unknown or retired generations cannot steal the selection", async () => {
    const setup = await ready()
    setup.dock.emit({ type: "tab-selected", payload: tab("tab-1", 99) })
    setup.dock.emit({ type: "tab-selected", payload: tab("unknown", 1) })
    expect(setup.controller.state.active).toEqual(tab("tab-1", 1))
  })

  test("a browser open announced before its reply keeps one tab with the newer navigation state", async () => {
    const dock = fakeDock()
    const controller = createAppDockController(dock.api, translate)
    controller.attach(element(), profileA)
    await until(() => controller.state.status === "ready")
    const release = Promise.withResolvers<void>()
    dock.gate(release.promise)
    controller.setURL("https://example.com/a")
    const launching = controller.launch()
    await until(() => dock.calls.some((call) => call[0] === "open"))
    dock.emit({ type: "tab-opened", payload: { ...tab("tab-1", 1), url: "https://example.com/a" } })
    dock.emit({
      type: "state",
      payload: {
        ...tab("tab-1", 1),
        url: "https://example.com/loaded",
        title: "Loaded",
        loading: false,
        audible: false,
      },
    })
    release.resolve()
    await launching
    expect(controller.state.tabs.map((item) => [item.tabID, item.url])).toEqual([
      ["tab-1", "https://example.com/loaded"],
    ])
    expect(controller.state.url).toBe("https://example.com/loaded")
  })

  test("closing the last browser tab stays on the browser side when the desktop attaches the workspace", async () => {
    const setup = await ready()
    await openLinux(setup, workspace("linux-1", 10))
    setup.controller.showBrowser()
    expect(setup.controller.state.mode).toBe("browser")
    setup.dock.onCloseTab(() => setup.dock.emit({ type: "tab-selected", payload: tab("linux-1", 10) }))
    await setup.controller.close()
    expect(setup.controller.state.mode).toBe("browser")
    expect(setup.controller.state.active).toBeUndefined()
    expect(setup.controller.state.tabs.map((item) => item.tabID)).toEqual(["linux-1"])
    expect(setup.dock.calls.at(-1)).toEqual(["hide", tab("linux-1", 10)])
  })

  test("closing the browser tabs around the workspace lands on the workspace, whose address bar never navigates", async () => {
    const setup = await ready()
    await openLinux(setup, workspace("linux-1", 10))
    setup.controller.showBrowser()
    const linux = setup.controller.state.tabs.find((item) => item.tabID === "linux-1")!
    await setup.controller.closeTabs(linux, "others")
    expect(setup.controller.state.active).toEqual(tab("linux-1", 10))
    expect(setup.controller.state.mode).toBe("linux")
    const calls = setup.dock.calls.length
    await setup.controller.launch()
    await setup.controller.duplicate(linux)
    expect(setup.dock.calls.slice(calls).filter((call) => call[0] === "navigate" || call[0] === "open")).toEqual([])
  })
})

function element() {
  return document.createElement("div")
}

function tab(tabID: string, generation: number) {
  return { tabID, generation }
}

const mounted: Element[] = []
afterEach(() => mounted.splice(0).forEach((item) => item.remove()))

// A Dock host laid out in the document beside the sidebar; happy-dom has no layout of its own.
function placed() {
  const root = document.createElement("div")
  const host = sized(element(), { x: 600, y: 100, width: 600, height: 500 })
  root.append(host)
  document.body.append(root)
  mounted.push(root)
  return host
}

// A portal like a Kobalte dialog's: its fixed-position overlay fills the window.
function overlay() {
  const portal = document.createElement("div")
  portal.append(sized(element(), { x: 0, y: 0, width: 1400, height: 900 }))
  document.body.append(portal)
  mounted.push(portal)
  return portal
}

function sized<T extends Element>(item: T, area: { x: number; y: number; width: number; height: number }) {
  Object.defineProperty(item, "getBoundingClientRect", {
    value: () => new DOMRect(area.x, area.y, area.width, area.height),
  })
  return item
}

async function settle() {
  for (let index = 0; index < 10; index++) await new Promise((resolve) => setTimeout(resolve, 0))
}

async function until(check: () => boolean) {
  for (let index = 0; index < 100 && !check(); index++) await new Promise((resolve) => setTimeout(resolve, 0))
  expect(check()).toBe(true)
}

type Manifest = Awaited<ReturnType<AppDockAPI["appDockGetManifest"]>>

// Mirrors the desktop registry: app-dock-open creates a missing profile and bumps the revision.
function fakeDock() {
  const calls: unknown[][] = []
  const listeners = new Set<Parameters<AppDockAPI["appDockEvent"]>[0]>()
  const state = {
    manifest: {
      version: 1,
      revision: 0,
      profiles: [{ id: "default", name: "default" }],
      activeProfileID: "default",
      tabs: { default: [] },
      bookmarks: [],
      history: [],
    } as Manifest,
    tabs: 0,
    gate: undefined as Promise<void> | undefined,
    failManifest: false,
    linux: [] as Array<(result: LinuxOpenResult) => void>,
    closing: undefined as ((tabID: string) => void) | undefined,
  }
  const api = {
    appDockOpen: async (url: string, _bounds: unknown, profile = "default") => {
      calls.push(["open", url, profile])
      const gate = state.gate
      state.gate = undefined
      const tabID = `tab-${++state.tabs}`
      const generation = state.tabs
      await gate
      if (!state.manifest.profiles.some((item) => item.id === profile))
        state.manifest = {
          ...state.manifest,
          revision: state.manifest.revision + 1,
          profiles: [...state.manifest.profiles, { id: profile, name: profile }],
          tabs: { ...state.manifest.tabs, [profile]: [] },
        }
      return { tabID, generation, url }
    },
    // The desktop accepts exactly a tab's ID and generation, so the raw argument is recorded.
    appDockSelect: async (target: TabIdentity) => {
      calls.push(["select", target])
    },
    appDockHide: async (target: TabIdentity) => {
      calls.push(["hide", target])
    },
    appDockOcclude: async (occluded: boolean) => {
      calls.push(["occlude", occluded])
    },
    appDockClose: async () => {
      calls.push(["close"])
    },
    appDockCloseTab: async (tabID: string) => {
      calls.push(["close-tab", tabID])
      state.closing?.(tabID)
    },
    appDockCloseTabs: async (tabID: string, scope: string) => {
      calls.push(["close-tabs", tabID, scope])
    },
    appDockLinuxOpen: (_bounds: unknown, profile: string) => {
      calls.push(["linux-open", profile])
      return new Promise<LinuxOpenResult>((resolve) => state.linux.push(resolve))
    },
    appDockLinuxWindows: async () => ({ status: "ready", windows: [] }),
    appDockNavigate: async (tabID: string, url: string) => {
      calls.push(["navigate", tabID, url])
      return { ok: true, url }
    },
    appDockResize: async (target: TabIdentity, bounds: unknown) => {
      calls.push(["resize", target, bounds])
    },
    appDockEvent: (callback: Parameters<AppDockAPI["appDockEvent"]>[0]) => {
      listeners.add(callback)
      return () => listeners.delete(callback)
    },
    appDockGetManifest: async () => {
      if (state.failManifest) throw new Error("manifest unavailable")
      return structuredClone(state.manifest)
    },
    appDockUpdateManifest: async (revision: number, manifest: Manifest) => {
      if (revision !== state.manifest.revision) return { status: "conflict", manifest: structuredClone(state.manifest) }
      const ids = state.manifest.profiles.map((item) => item.id)
      if (manifest.profiles.length !== ids.length || Object.keys(manifest.tabs).some((id) => !ids.includes(id)))
        throw new Error("Invalid MCP Dock manifest")
      state.manifest = { ...structuredClone(manifest), revision: revision + 1 }
      return { status: "updated", manifest: structuredClone(state.manifest) }
    },
  }
  return {
    api: api as unknown as AppDockAPI,
    calls,
    manifest: () => state.manifest,
    subscriptions: () => listeners.size,
    emit: (event: Parameters<Parameters<AppDockAPI["appDockEvent"]>[0]>[0]) =>
      listeners.forEach((listener) => listener(event)),
    gate: (promise: Promise<void>) => (state.gate = promise),
    seed: (manifest: Pick<Manifest, "profiles" | "tabs">) => (state.manifest = { ...state.manifest, ...manifest }),
    failManifest: (value: boolean) => (state.failManifest = value),
    linuxPending: () => state.linux.length,
    resolveLinux: (result: LinuxOpenResult) => state.linux.shift()?.(result),
    onCloseTab: (callback: (tabID: string) => void) => (state.closing = callback),
  }
}

import { expect, test } from "bun:test"
import { createLatestWorkerQueue } from "./markdown-worker-queue"

test("keeps only the latest queued request for each key", async () => {
  const processed: number[] = []
  const superseded: number[] = []
  let release = () => {}
  const blocked = new Promise<void>((resolve) => {
    release = resolve
  })
  const queue = createLatestWorkerQueue<{ id: number; key: string }>({
    run: async (request) => {
      processed.push(request.id)
      if (request.id === 1) await blocked
    },
    supersede: (request) => superseded.push(request.id),
    dispose: () => {},
  })

  queue.highlight({ id: 1, key: "code" })
  await Promise.resolve()
  queue.highlight({ id: 2, key: "code" })
  queue.highlight({ id: 3, key: "code" })
  queue.highlight({ id: 4, key: "code" })

  expect(queue.pending()).toBe(1)
  expect(superseded).toEqual([2, 3])
  release()
  await queue.idle()
  expect(processed).toEqual([1, 4])
})

test("serializes disposal before a later request for the same key", async () => {
  const events: string[] = []
  const queue = createLatestWorkerQueue<{ id: number; key: string }>({
    run: async (request) => {
      events.push(`highlight:${request.id}`)
    },
    supersede: (request) => events.push(`supersede:${request.id}`),
    dispose: (key) => events.push(`dispose:${key}`),
  })

  queue.highlight({ id: 1, key: "code" })
  queue.dispose("code")
  queue.highlight({ id: 2, key: "code" })
  await queue.idle()

  expect(events).toEqual(["supersede:1", "dispose:code", "highlight:2"])
})

