import { checksum } from "@orchestra/core/util/encode"
import type { FilePartSource } from "@/v2-types"
import { batch, createMemo, type Accessor } from "solid-js"
import { createStore, type SetStoreFunction } from "solid-js/store"
import type { FileSelection } from "@/context/file"
import { Persist, persisted } from "@/utils/persist"
import type { ServerScope } from "@/utils/server-scope"
import type { BlobReference } from "@/utils/draft-store"
import type { Platform } from "@/context/platform"

interface PartBase {
  content: string
  start: number
  end: number
}

export interface TextPart extends PartBase {
  type: "text"
}

export interface FileAttachmentPart extends PartBase {
  type: "file"
  path: string
  selection?: FileSelection
  mime?: string
  filename?: string
  url?: string
  source?: FilePartSource
}

export interface AgentPart extends PartBase {
  type: "agent"
  name: string
}

export interface ImageAttachmentPart {
  type: "image"
  id: string
  filename: string
  sourcePath?: string
  mime: string
  blob: BlobReference
}

export type ContentPart = TextPart | FileAttachmentPart | AgentPart | ImageAttachmentPart
export type Prompt = ContentPart[]

export type PromptModel = {
  providerID: string
  modelID: string
  variant?: string | null
}

export type FileContextItem = {
  type: "file"
  path: string
  selection?: FileSelection
  comment?: string
  commentID?: string
  commentOrigin?: "review" | "file"
  preview?: string
}

export type ContextItem = FileContextItem
export type PromptScope = { draftID: string } | { dir: string; id?: string }

export const DEFAULT_PROMPT: Prompt = [{ type: "text", content: "", start: 0, end: 0 }]

export type PromptStore = {
  prompt: Prompt
  cursor?: number
  model?: PromptModel
  context: {
    items: (ContextItem & { key: string })[]
  }
}

type InitialPrompt = {
  prompt?: string
  model?: PromptModel
}

function isSelectionEqual(a?: FileSelection, b?: FileSelection) {
  if (!a && !b) return true
  if (!a || !b) return false
  return (
    a.startLine === b.startLine && a.startChar === b.startChar && a.endLine === b.endLine && a.endChar === b.endChar
  )
}

function isPartEqual(partA: ContentPart, partB: ContentPart) {
  switch (partA.type) {
    case "text":
      return partB.type === "text" && partA.content === partB.content
    case "file":
      return (
        partB.type === "file" &&
        partA.path === partB.path &&
        partA.mime === partB.mime &&
        partA.filename === partB.filename &&
        isSelectionEqual(partA.selection, partB.selection)
      )
    case "agent":
      return partB.type === "agent" && partA.name === partB.name
    case "image":
      return partB.type === "image" && partA.id === partB.id
  }
}

export function isPromptEqual(promptA: Prompt, promptB: Prompt): boolean {
  if (promptA.length !== promptB.length) return false
  for (let i = 0; i < promptA.length; i++) {
    if (!isPartEqual(promptA[i], promptB[i])) return false
  }
  return true
}

function cloneSelection(selection?: FileSelection) {
  if (!selection) return undefined
  return { ...selection }
}

function clonePart(part: ContentPart): ContentPart {
  if (part.type === "text") return { ...part }
  if (part.type === "image") return { ...part }
  if (part.type === "agent") return { ...part }
  return {
    ...part,
    selection: cloneSelection(part.selection),
  }
}

function clonePrompt(prompt: Prompt): Prompt {
  return prompt.map(clonePart)
}

function contextItemKey(item: ContextItem) {
  if (item.type !== "file") return item.type
  const start = item.selection?.startLine
  const end = item.selection?.endLine
  const key = `${item.type}:${item.path}:${start}:${end}`

  if (item.commentID) return `${key}:c=${item.commentID}`
  const comment = item.comment?.trim()
  if (!comment) return key
  const digest = checksum(comment) ?? comment
  return `${key}:c=${digest.slice(0, 8)}`
}

export function isCommentItem(item: ContextItem | (ContextItem & { key: string })) {
  return item.type === "file" && !!item.comment?.trim()
}

function createPromptActions(setStore: SetStoreFunction<PromptStore>) {
  return {
    set(prompt: Prompt, cursorPosition?: number) {
      const next = clonePrompt(prompt)
      batch(() => {
        setStore("prompt", next)
        if (cursorPosition !== undefined) setStore("cursor", cursorPosition)
      })
    },
    reset() {
      batch(() => {
        setStore("prompt", clonePrompt(DEFAULT_PROMPT))
        setStore("cursor", 0)
      })
    },
  }
}

function promptTarget(serverScope: ServerScope, scope: PromptScope) {
  if ("draftID" in scope) return Persist.prompt(Persist.draft(scope.draftID, "prompt"))
  const legacy = `${scope.dir}/prompt${scope.id ? "/" + scope.id : ""}.v2`
  return Persist.prompt(Persist.serverScoped(serverScope, scope.dir, scope.id, "prompt", [legacy]))
}

function promptStore(initial?: InitialPrompt): PromptStore {
  const text = initial?.prompt
  return {
    prompt:
      text === undefined ? clonePrompt(DEFAULT_PROMPT) : [{ type: "text", content: text, start: 0, end: text.length }],
    cursor: text === undefined ? undefined : text.length,
    model: initial?.model ? { ...initial.model } : undefined,
    context: {
      items: [],
    },
  }
}

function createPromptStateValue(store: PromptStore, setStore: SetStoreFunction<PromptStore>) {
  const actions = createPromptActions(setStore)
  const value = {
    store: [() => store, setStore] as [Accessor<PromptStore>, SetStoreFunction<PromptStore>],
    current: () => store.prompt,
    cursor: createMemo(() => store.cursor),
    dirty: () => !isPromptEqual(store.prompt, DEFAULT_PROMPT),
    model: {
      current: () => store.model,
      set: (model: PromptModel | undefined) => setStore("model", model),
    },
    context: {
      items: createMemo(() => store.context.items),
      add(item: ContextItem) {
        const key = contextItemKey(item)
        if (store.context.items.find((x) => x.key === key)) return
        setStore("context", "items", (items) => [...items, { key, ...item }])
      },
      remove(key: string) {
        setStore("context", "items", (items) => items.filter((x) => x.key !== key))
      },
      removeComment(path: string, commentID: string) {
        setStore("context", "items", (items) =>
          items.filter((item) => !(item.type === "file" && item.path === path && item.commentID === commentID)),
        )
      },
      updateComment(path: string, commentID: string, next: Partial<FileContextItem> & { comment?: string }) {
        setStore("context", "items", (items) =>
          items.map((item) => {
            if (item.type !== "file" || item.path !== path || item.commentID !== commentID) return item
            const value = { ...item, ...next }
            return { ...value, key: contextItemKey(value) }
          }),
        )
      },
      replaceComments(items: FileContextItem[]) {
        setStore("context", "items", (current) => [
          ...current.filter((item) => !isCommentItem(item)),
          ...items.map((item) => ({ ...item, key: contextItemKey(item) })),
        ])
      },
    },
    set: actions.set,
    reset: actions.reset,
    capture: () => value,
  }
  return value
}

function createPersistedPrompt(target: ReturnType<typeof promptTarget>, initial?: InitialPrompt, platform?: Platform) {
  const [store, setStore, _, ready] = persisted(target, createStore<PromptStore>(promptStore(initial)), platform)
  return { ready, ...createPromptStateValue(store, setStore) }
}

export function createPromptSession(
  serverScope: ServerScope,
  scope: PromptScope,
  initial?: InitialPrompt,
  platform?: Platform,
) {
  return createPersistedPrompt(promptTarget(serverScope, scope), initial, platform)
}

export function createDraftPromptSession(draftID: string, initial?: InitialPrompt) {
  return createPersistedPrompt(Persist.prompt(Persist.draft(draftID, "prompt")), initial)
}

export type PromptSession = ReturnType<typeof createPromptSession>

export function createPromptReady(session: Accessor<PromptSession>) {
  return Object.defineProperty(() => session().ready(), "promise", {
    get: () => session().ready.promise,
  }) as (() => boolean) & { readonly promise: Promise<unknown> | undefined }
}

export function createPromptState(initial?: InitialPrompt) {
  const [store, setStore] = createStore<PromptStore>(promptStore(initial))
  const ready = Object.assign(() => true, { promise: Promise.resolve(true) })
  return {
    ready,
    ...createPromptStateValue(store, setStore),
  }
}

import { createSignal } from "solid-js"
import { Orchestra } from "@orchestra/client"
import type { ServerConnection } from "@/context/server"
import { authTokenFromCredentials } from "./server"
import type { ModelPolicySnapshot, SubagentModelPolicy } from "@/components/subagent-model-rules"
import { SessionManagementUnsupported } from "./session-management-errors"
import { normalizeSessionInfo, type AppSession } from "./session"
import { directoryKey } from "@/context/global-sync/utils"

/** Construct once inside the server SDK: fetch must carry that context's abort signal. */
export function createSessionManagementForServer(input: {
  server: ServerConnection.HttpBase
  fetch: typeof globalThis.fetch
  /** Settles when the server answers its health route; archive routes are offered from then on. */
  ready: Promise<void>
  signal?: AbortSignal
}) {
  const http = { ...input.server }
  const fetcher = input.fetch
  const lifetime = input.signal
  const headers = http.password
    ? { Authorization: `Basic ${authTokenFromCredentials({ username: http.username, password: http.password })}` }
    : undefined
  const client = Orchestra.make({
    baseUrl: http.url,
    // Declared 404s can be decoded to domain errors without their HTTP status. Classify at the transport boundary.
    fetch: Object.assign(
      async (request: string | URL | Request, init?: RequestInit) => {
        const response = await fetcher(request, init)
        if (response.status === 404 && response.headers.get("content-type")?.includes("application/json")) {
          const body: unknown = await response.clone().json().catch(() => undefined)
          if (body && typeof body === "object" && "_tag" in body && body._tag === "SessionNotFoundError") return response
        }
        if (response.status === 404 || response.status === 405 || response.status === 501) {
          await response.body?.cancel().catch(() => {})
          throw new SessionManagementUnsupported()
        }
        return response
      },
      { preconnect: fetcher.preconnect },
    ),
    headers,
  })
  // Every server speaks the V2 session routes; archive is available once the server is ready.
  const [archiveRouted, setArchiveRouted] = createSignal(false)
  let archiveProbe: Promise<boolean> | undefined
  const archiveRoutes = () => {
    if (archiveProbe) return archiveProbe
    archiveProbe = input.ready.then(() => true)
    void archiveProbe.then((routed) => setArchiveRouted(routed), () => {})
    return archiveProbe
  }
  const writes = new Map<string, Promise<SubagentModelPolicy>>()
  const versions = new Map<string, number>()
  lifetime?.addEventListener("abort", () => {
    writes.clear()
    versions.clear()
  }, { once: true })
  return {
    /** Resolves true when archive, restore and the archived list can use the V2 session routes. */
    archiveRoutes,
    hasArchiveRoutes() {
      void archiveRoutes()
      return archiveRouted()
    },
    listArchived(directory: string) {
      return runSessionManagementOperation(lifetime, async () => {
        if (!(await archiveRoutes())) throw new SessionManagementUnsupported()
        lifetime?.throwIfAborted()
        const sessions: AppSession[] = []
        let cursor: string | undefined
        while (true) {
          const page = await client.sessions.list({ directory, includeArchived: true, order: "desc", limit: 100, cursor })
          lifetime?.throwIfAborted()
          sessions.push(...page.data.map(normalizeSessionInfo))
          if (!page.data.length || !page.cursor.next) break
          cursor = page.cursor.next
        }
        return sessions.filter((session) =>
          session.time.archived !== undefined && directoryKey(session.directory) === directoryKey(directory),
        )
      })
    },
    getSubagentModels(sessionID: string): Promise<SubagentModelPolicy> {
      return runSessionManagementOperation(lifetime, async () => {
        await input.ready
        lifetime?.throwIfAborted()
        const policy = await client.sessions.getSubagentModels({ sessionID })
        lifetime?.throwIfAborted()
        return policy
      })
    },
    readSubagentModels(sessionID: string): Promise<ModelPolicySnapshot> {
      return runSessionManagementOperation(lifetime, async () => {
        await input.ready
        lifetime?.throwIfAborted()
        // The full snapshot anchors policy freshness; policy-only GET/PUT responses have no revision.
        const snapshot = await client.sessions.get({ sessionID })
        lifetime?.throwIfAborted()
        return { policy: snapshot.subagentModels ?? { mode: "inherit" }, timestamp: snapshot.time.updated }
      })
    },
    setSubagentModels(sessionID: string, policy: SubagentModelPolicy): Promise<SubagentModelPolicy> {
      if (lifetime?.aborted) return Promise.reject(lifetime.reason)
      versions.set(sessionID, (versions.get(sessionID) ?? 0) + 1)
      const previous = writes.get(sessionID)
      const write = runSessionManagementOperation(lifetime, async () => {
        // Only an explicit new write may retry a failed predecessor; dispatch waits must retain its failure.
        await (previous ? previous.catch(() => undefined) : Promise.resolve())
        await input.ready
        lifetime?.throwIfAborted()
        const acknowledged = await client.sessions.setSubagentModels({ sessionID, policy })
        lifetime?.throwIfAborted()
        if (writes.get(sessionID) === write) writes.delete(sessionID)
        return acknowledged
      })
      writes.set(sessionID, write)
      void write.catch(() => {})
      return write
    },
    subagentModelsWriteVersion(id: string): number {
      return versions.get(id) ?? 0
    },
    waitSubagentModels(id: string): Promise<void> {
      // Capture the barrier before lifecycle cleanup can clear the map; a disposed lifetime still rejects the wait.
      const current = writes.get(id)
      return runSessionManagementOperation(lifetime, async () => {
        let write = current ?? writes.get(id)
        while (write) {
          const failure = await write.then(() => undefined, (error: unknown) => ({ error }))
          lifetime?.throwIfAborted()
          const latest = writes.get(id)
          if (latest && latest !== write) {
            write = latest
            continue
          }
          if (failure && latest === write) throw failure.error
          return
        }
      })
    },
    archive(sessionID: string, archived: boolean) {
      return runSessionManagementOperation(lifetime, async () => {
        if (!(await archiveRoutes())) throw new SessionManagementUnsupported()
        lifetime?.throwIfAborted()
        await client.sessions.archive({ sessionID, archived })
      })
    },
  }
}

export type SessionManagement = ReturnType<typeof createSessionManagementForServer>

/** Race the complete generated operation, including readiness and response body decoding. */
async function runSessionManagementOperation<T>(lifetime: AbortSignal | undefined, load: () => Promise<T>): Promise<T> {
  lifetime?.throwIfAborted()
  if (!lifetime) return load()
  const cancelled = Promise.withResolvers<never>()
  const onAbort = () => cancelled.reject(lifetime.reason)
  lifetime.addEventListener("abort", onAbort, { once: true })
  const operation = Promise.resolve().then(() => {
    lifetime.throwIfAborted()
    return load()
  })
  return Promise.race([operation, cancelled.promise])
    .then((value) => {
      lifetime.throwIfAborted()
      return value
    })
    .finally(() => lifetime.removeEventListener("abort", onAbort))
}

import { createSimpleContext } from "@orchestra/ui/context"
import { queryOptions, useQuery, useQueryClient } from "@tanstack/solid-query"
import { createEffect, onCleanup } from "solid-js"
import type { WslServersState } from "./types"
import { usePlatform } from "../context/platform"

const wslServersQueryKey = ["platform", "wslServers"] as const

export const { use: useWslServers, provider: WslServersProvider } = createSimpleContext({
  name: "WslServers",
  init: () => {
    const platform = usePlatform()
    const queryClient = useQueryClient()
    const query = useQuery(() => {
      const api = platform.wslServers
      return queryOptions<WslServersState>({
        queryKey: wslServersQueryKey,
        queryFn: () => api!.getState(),
        enabled: !!api,
        staleTime: Number.POSITIVE_INFINITY,
        gcTime: Number.POSITIVE_INFINITY,
      })
    })

    createEffect(() => {
      const api = platform.wslServers
      if (!api) return
      const off = api.subscribe((event) => {
        queryClient.setQueryData(wslServersQueryKey, event.state)
      })
      onCleanup(off)
    })

    return query as typeof query & { readonly data: WslServersState | undefined }
  },
})

