} from "solid-js"
import { useLanguage } from "@/context/language"
import { useSDK } from "@/context/sdk"
import { useSync } from "@/context/sync"
import { useParams } from "@solidjs/router"
import type { EvidenceComposerActions } from "./composer/session-evidence-actions"
import { createEvidenceCache, type ExecutionEvidence, isShellTool } from "./orchestra-evidence-data"
import { EvidenceActions } from "./orchestra-evidence-actions"
import { type TestCountKey, type TestCounts, type TestRunner } from "./orchestra-evidence-parse"

// The timeline seam: one call per mounted assistant part. Returning undefined keeps the
// existing part renderer; shell parts get a wrapper that falls back to it until a
// completed run yields evidence, so the output is never rendered twice.
export type ExecutionEvidenceInput = {
  part: Accessor<Part>
  message: Accessor<Message>
  output: () => JSX.Element
  openOutput: () => void
  onSizeChange?: () => void
}

const RUNNER_LABEL: Record<TestRunner, string> = {
  bun: "bun test",
  vitest: "Vitest",
  jest: "Jest",
  playwright: "Playwright",
  pytest: "pytest",
  go: "go test",
  cargo: "cargo test",
}
const COUNT_ORDER: TestCountKey[] = [
  "failed",
  "errors",
  "interrupted",
  "passed",
  "flaky",
  "skipped",
  "todo",
  "notRun",
  "noTests",
]
const FAILURES_SHOWN = 6

export function createExecutionEvidenceRenderer(input: {
  actions: EvidenceComposerActions
  sessionKey: Accessor<string>
}) {
  const sdk = useSDK()
  const sync = useSync()
  const params = useParams()
  const cache = createEvidenceCache()
  const sources = createMemo(
    () => new Map((sync().data.session_message[params.id ?? ""] ?? []).map((message) => [message.id, message])),
  )
  createEffect(on(input.sessionKey, () => cache.clear(), { defer: true }))

  return (seam: ExecutionEvidenceInput) => {
    const initial = seam.part()
    if (initial.type !== "tool" || !isShellTool(initial.tool)) return
    const evidence = createMemo(() => {
      const part = seam.part()
      if (part.type !== "tool") return
      const message = seam.message()
      const parent = message.role === "assistant" ? sources().get(message.parentID) : undefined
      // Live projection can also index its synthetic assistant. The raw shell
      // parent remains authoritative, including interruption and missing end time.
      const source = parent?.type === "shell" ? parent : sources().get(message.id)
      return cache.read(part, { scope: sdk().scope, directory: sdk().directory }, source)
    })
    return (
      <Show when={evidence()} fallback={seam.output()}>
        {(value) => <EvidenceCard evidence={value()} seam={seam} actions={input.actions} />}
      </Show>
    )
  }
}

function EvidenceCard(props: {
  evidence: ExecutionEvidence
  seam: ExecutionEvidenceInput
  actions: EvidenceComposerActions
}) {
  const language = useLanguage()
  const id = createUniqueId()
  const [tab, setTab] = createSignal<"result" | "output">("result")
  const summary = () => props.evidence.summary
  const runner = () => RUNNER_LABEL[props.evidence.runner]
  const select = (next: "result" | "output") => {
    setTab(next)
    if (next === "output") props.seam.openOutput()
    props.seam.onSizeChange?.()
  }
  const showOutput = () => {
    select("output")
    document.getElementById(`${id}-output-tab`)?.focus()
  }
  const stateLabel = () => {
    const state = props.evidence.state
    if (state === "partial") return language.t("orchestra.output.partial")
    return language.t(`orchestra.evidence.state.${state}`)
  }
  const counts = (values: TestCounts) =>
    COUNT_ORDER.flatMap((key) => {
      const value = values[key]
      if (value === undefined) return []
      return [{ key, text: language.t(`orchestra.evidence.count.${key}`, { count: value }) }]
    })
  const result = createMemo(() => {
    const value = summary()
    const parts = [stateLabel(), ...(value ? counts(value.tests.counts).map((item) => item.text) : [])]
    const exit = props.evidence.exit
    return `${parts.join(", ")} (${exit === undefined ? language.t("orchestra.output.unknownExit") : language.t("orchestra.evidence.exit", { code: exit })})`
  })
  const keyDown = (event: KeyboardEvent) => {
    const order = ["result", "output"] as const
    const index = order.indexOf(tab())
    const next =
      event.key === "ArrowRight" || event.key === "ArrowLeft"
        ? order[(index + 1) % order.length]
        : event.key === "Home"
          ? order[0]
          : event.key === "End"
            ? order[1]
            : undefined
    if (!next) return
    event.preventDefault()
    select(next)
    document.getElementById(`${id}-${next}-tab`)?.focus()
  }

  return (
    <section
      data-orchestra-evidence
      data-part-id={props.evidence.source.partID}
      data-state={props.evidence.state}
      aria-label={language.t("orchestra.evidence.label", { command: props.evidence.source.command })}
    >
      <div data-slot="evidence-card">
        <div data-slot="evidence-tabs">
          <div data-slot="evidence-tablist" role="tablist" onKeyDown={keyDown}>
            <For each={["result", "output"] as const}>
              {(item) => (
                <button
                  type="button"
                  role="tab"
                  id={`${id}-${item}-tab`}
                  aria-selected={tab() === item}
                  aria-controls={`${id}-${item}`}
                  tabIndex={tab() === item ? 0 : -1}
                  onClick={() => select(item)}
                >
                  {language.t(item === "result" ? "orchestra.evidence.tab.result" : "orchestra.evidence.tab.output")}
                </button>
              )}
            </For>
          </div>
          <code data-slot="evidence-command" title={props.evidence.source.command}>
            <bdi dir="ltr">{props.evidence.source.command}</bdi>
          </code>
        </div>
        <div
          role="tabpanel"
          id={`${id}-result`}
          aria-labelledby={`${id}-result-tab`}
          data-slot="evidence-result"
          hidden={tab() !== "result"}
        >
          <div data-slot="evidence-head">
            <Switch>
              <Match when={props.evidence.state === "partial"}>
                <span data-slot="evidence-badge">{stateLabel()}</span>
              </Match>
              <Match when={true}>
                <span data-slot="evidence-status">
                  <Icon
                    name={
                      props.evidence.state === "passed"
                        ? "check"
                        : props.evidence.state === "failed"
                          ? "outline-xmark"
                          : "status"
                    }
                    size="small"
                    aria-hidden="true"
                  />
                  <bdi>{stateLabel()}</bdi>
                </span>
              </Match>
            </Switch>
            <button type="button" data-slot="evidence-link" onClick={showOutput}>
              <bdi>{language.t("orchestra.output.open")}</bdi>
              <Icon name="outline-square-arrow" size="small" aria-hidden="true" />
            </button>
          </div>
          <Show
            when={summary()}
            fallback={
              <div data-slot="evidence-partial">
                <p>{language.t("orchestra.evidence.partialRetained")}</p>
                <Show when={props.evidence.outputPath}>
                  {(path) => (
                    <p data-slot="evidence-meta">{language.t("orchestra.evidence.outputPath", { path: path() })}</p>
                  )}
                </Show>
              </div>
            }
          >
            {(value) => (
              <>
                <dl data-slot="evidence-rows">
                  <For
                    each={[value().groups, value().tests].flatMap((row) =>
                      row?.counts && Object.keys(row.counts).length > 0 ? [row] : [],
                    )}
                  >
                    {(row) => (
                      <div data-slot="evidence-row">
                        <dt>{language.t(`orchestra.evidence.unit.${row.unit}`)}</dt>
                        <dd>
                          <For each={counts(row.counts!)}>
                            {(item) => (
                              <span data-count={item.key}>
                                <bdi>{item.text}</bdi>
                              </span>
                            )}
                          </For>
                          <Show when={row.total !== undefined}>
                            <span data-slot="evidence-total">({row.total})</span>
                          </Show>
                        </dd>
                      </div>
                    )}
                  </For>
                </dl>
                <Show when={value().groups && !value().groups!.counts ? value().groups : undefined}>
                  {(group) => (
                    <p data-slot="evidence-line">
                      {language.t(
                        group().unit === "binaries"
                          ? "orchestra.evidence.executed.binaries"
                          : "orchestra.evidence.executed.files",
                        { count: group().total },
                      )}
                    </p>
                  )}
                </Show>
                <p
                  data-slot="evidence-line"
                  data-exit={props.evidence.exit === undefined ? "unknown" : props.evidence.exit}
                >
                  {props.evidence.exit === undefined
                    ? language.t("orchestra.output.unknownExit")
                    : language.t("orchestra.evidence.exit", { code: props.evidence.exit })}
                </p>
                <Show when={value().failures.length > 0}>
                  <div data-slot="evidence-failures">
                    <span>{language.t("orchestra.evidence.failures")}</span>
                    <ul>
                      <For each={value().failures.slice(0, FAILURES_SHOWN)}>
                        {(name) => (
                          <li dir="ltr" title={name}>
                            {name}
                          </li>
                        )}
                      </For>
                    </ul>
                    <Show when={value().failures.length > FAILURES_SHOWN}>
                      <span data-slot="evidence-meta">
                        {language.t("orchestra.evidence.failures.more", {
                          count: value().failures.length - FAILURES_SHOWN,
                        })}
                      </span>
                    </Show>
                  </div>
                </Show>
                <p data-slot="evidence-meta">
                  <bdi>
                    {value().duration
                      ? language.t("orchestra.evidence.reportedDuration", {
                          runner: runner(),
                          duration: value().duration!,
                        })
                      : language.t("orchestra.evidence.reported", { runner: runner() })}
                  </bdi>
                </p>
                <p data-slot="evidence-meta">
                  <bdi>
                    {props.evidence.durationMs === undefined
                      ? language.t("orchestra.evidence.durationUnknown")
                      : language.t("orchestra.evidence.duration", { duration: props.evidence.durationMs })}
                  </bdi>
                </p>
              </>
            )}
          </Show>
        </div>
        <div
          role="tabpanel"
          id={`${id}-output`}
          aria-labelledby={`${id}-output-tab`}
          data-slot="evidence-output"
          hidden={tab() !== "output"}
        >
          {/* The retained output is a full tool part: mount it only while its tab is shown. */}
          <Show when={tab() === "output"}>{props.seam.output()}</Show>
        </div>
      </div>
      <p data-slot="evidence-meta">
        <bdi>{language.t("orchestra.evidence.revisionUnlinked")}</bdi>
      </p>
      <EvidenceActions evidence={props.evidence} result={result()} actions={props.actions} />
    </section>
  )
}

import { Orchestra } from "@orchestra/client"
import { CapabilityArtifactManagement } from "@orchestra/schema/capability-artifact-management"
import { CapabilityManagement } from "@orchestra/schema/capability-management"
import type { SessionID } from "@orchestra/schema/session-id"
import { Schema } from "effect"
import type { ServerConnection } from "@/context/server"
import { authTokenFromCredentials } from "@/utils/server"
import type { ArtifactRef, ArtifactsApi, ArtifactsOptions } from "./artifacts-model"

/** One Session's artifact transport on the selected host. Every call is scoped to that Session and Location. */
export function createArtifactsApi(input: { server: ServerConnection.HttpBase; directory: string; sessionID: SessionID;
  fetch?: typeof globalThis.fetch }): ArtifactsTransport {
  const location = Object.freeze({ directory: input.directory })
  const sessionID = input.sessionID
  const headers = input.server.password ? { Authorization: `Basic ${authTokenFromCredentials({
    username: input.server.username, password: input.server.password })}` } : undefined
  const client = Orchestra.make({ baseUrl: input.server.url, fetch: input.fetch, headers })
  const request = (options?: ArtifactsOptions) => ({ signal: options?.signal })
  const receipt = Schema.decodeUnknownSync(CapabilityManagement.Receipt, { onExcessProperty: "error" })
  const content = (ref: ArtifactRef) => {
    const url = new URL(`/api/capability/sessions/${encodeURIComponent(sessionID)}/artifacts/${encodeURIComponent(ref.id)}/${ref.revision}/content`,
      input.server.url)
    url.searchParams.set("location[directory]", input.directory)
    return url.href
  }
  return Object.freeze({
    list: (after, options) => client.artifacts.list({ sessionID, location, limit: 32, ...(after === undefined ? {} : { after }) },
      request(options)).then(Schema.decodeUnknownSync(CapabilityArtifactManagement.ArtifactPage, { onExcessProperty: "error" })),
    get: (ref, options) => client.artifacts.get({ sessionID, location, artifactID: ref.id, revision: String(ref.revision) },
      request(options)).then(Schema.decodeUnknownSync(CapabilityArtifactManagement.Artifact, { onExcessProperty: "error" })),
    share: (ref, targetSessionID, key, options) => client.artifacts.share({ sessionID, location, artifactID: ref.id,
      revision: String(ref.revision), targetSessionID, "idempotency-key": key }, request(options)).then(receipt),
    pin: (ref, pinned, key, options) => client.artifacts.pin({ sessionID, location, artifactID: ref.id,
      revision: String(ref.revision), pinned, "idempotency-key": key }, request(options)).then(receipt),
    remove: (ref, key, options) => client.artifacts.removeReference({ sessionID, location, artifactID: ref.id,
      revision: String(ref.revision), "idempotency-key": key }, request(options)).then(receipt),
    // The generated client has no binary endpoint; this URL keys the selection, and `read` and `ticket` serve its bytes.
    content,
    // Capability routes read credentials only from the Authorization header, which a media element cannot send.
    read: (ref, signal) => (input.fetch ?? globalThis.fetch)(content(ref), { headers, signal }).then((response) => {
      if (!response.ok) throw response.status === 401 || response.status === 403 ? "authorization" : "request"
      return response.blob()
    }),
    // A short-lived header-free URL, so a media element can stream and seek with its own range requests.
    ticket: (ref, signal) => client.artifacts.contentTicket({ sessionID, location, artifactID: ref.id,
      revision: String(ref.revision) }, { signal }).then((ticket) => ({ url: new URL(ticket.url, input.server.url).href,
      expiresAt: ticket.expiresAt })),
  } satisfies ArtifactsTransport)
}

type ArtifactsTransport = ArtifactsApi & {
  read: (ref: ArtifactRef, signal?: AbortSignal) => Promise<Blob>
  ticket: (ref: ArtifactRef, signal?: AbortSignal) => Promise<{ url: string; expiresAt: number }>
}

import { Capability } from "@orchestra/schema/capability"
import { Option, Schema } from "effect"
import type { Part } from "@/v2-wire"

/**
 * The latest status the agent observed for one process, never live state: no route exposes process state, so this
 * derives only from `process_control` results in the transcript.
 */
export type ProcessItem = Readonly<{
  id: Capability.JobRef["id"]
  /** From the start call, when the transcript still holds it. */
  argv?: string
  state: Capability.JobState
  exit?: Readonly<{ code?: number; signal?: string }>
  /** When the tool call that reported the latest status finished. */
  time: number
  /** The tool call that reported the latest status; the transcript anchor the item links to. */
  callID: string
}>

const terminal = new Set<Capability.JobState>(["completed", "failed", "cancelled", "lost"])

/** One item per process, most recently reported first. */
export function processItems(parts: readonly Part[]): readonly ProcessItem[] {
  const reports = parts.flatMap((part, order) => {
    if (part.type !== "tool" || part.tool !== "process_control" || part.state.status !== "completed") return []
    // A truncated or foreign output is skipped rather than guessed at.
    const output = Schema.decodeUnknownOption(Schema.UnknownFromJsonString)(part.state.output)
      .pipe(Option.flatMap(Schema.decodeUnknownOption(Output)))
    if (Option.isNone(output)) return []
    const start = Schema.decodeUnknownOption(Start)(part.state.input)
    const time = part.state.time.end
    const callID = part.callID
    return ("items" in output.value ? output.value.items : [output.value.status]).map((status) => ({ status, order, time,
      callID, argv: Option.isSome(start) ? summary(start.value.argv) : undefined }))
  })
  const latest = Map.groupBy(reports, (report) => report.status.process.id)
  return [...latest.entries()].map(([id, group]) => {
    const report = group.reduce((best, next) => next.time > best.time || (next.time === best.time && next.order > best.order)
      ? next : best)
    return { id, argv: group.find((row) => row.argv !== undefined)?.argv, state: report.status.state,
      exit: report.status.exit, time: report.time, callID: report.callID }
  }).toSorted((a, b) => b.time - a.time || b.id.localeCompare(a.id))
}

/** How many processes the header indicator counts; `unknown` and other non-terminal states count as running. */
export function runningCount(items: readonly ProcessItem[]) {
  return items.filter((item) => !terminal.has(item.state)).length
}

function summary(argv: readonly string[]) {
  return argv.map((arg) => /\s|^$/.test(arg) ? JSON.stringify(arg) : arg).join(" ")
}

const Status = Schema.Struct({
  process: Capability.JobRef,
  state: Capability.JobState,
  exit: Schema.optional(Schema.Struct({ code: Schema.optional(Schema.Int), signal: Schema.optional(Schema.String) })),
})
const Output = Schema.Union([
  Schema.Struct({ action: Schema.Literal("list"), items: Schema.Array(Status) }),
  Schema.Struct({ action: Schema.Literals(["start", "status", "write", "submit", "close-input", "log", "wait", "stop", "transfer"]),
    status: Status }),
])
const Start = Schema.Struct({ action: Schema.Literal("start"), argv: Schema.Array(Schema.String).check(Schema.isMinLength(1)) })

import { createMemo } from "solid-js"
import { createStore } from "solid-js/store"
import type { PermissionRequest, QuestionRequest } from "@/v2-types"
import type { AssistantMessage, Message, Part, Session, SessionStatus } from "@/v2-wire"

import { useServerSDK } from "@/context/server-sdk"
import { useSync } from "@/context/sync"
import { ScopedKey, type ServerScope } from "@/utils/server-scope"
import { sessionTitle } from "@/utils/session-title"
import { useSessionLayout } from "./session-layout"
import { agentKey } from "@/context/agent-identity"
import { isTaskTool, taskAgentType } from "@orchestra/core/util/task-tool"

type ToolPart = Extract<Part, { type: "tool" }>

export type TasksItemState = "running" | "needs-input" | "completed" | "error" | "interrupted" | "unknown"

export interface TasksItem {
  /** Server-qualified key, so rows from two servers never collide. */
  key: string
  kind: "agent" | "shell"
  headline: string
  /** Stable id of the Task's agent: the key. */
  agentID?: string
  /** The agent's display label, rendered as `@<label>`; renaming a seat never changes `agentID`. */
  agent?: string
  state: TasksItemState
  /** Undefined when no synced record says when the work started. */
  startTime?: number
  /** Undefined unless a terminal record carries the end time. */
  endTime?: number
  /** Child session id — the official join key (task.ts metadata.sessionId). */
  childId?: string
  /** Parent session that spawned the work. */
  sessionId: string
  /** References from the loaded projection, not guessed from timestamps or call IDs. */
  sourceMessageID?: string
  sourcePartID?: string
  callID?: string
  originUserMessageID?: string
  /** Nested subagent count ((+N), Claude panel parity). */
  nested?: number
  stats?: TaskStats
}

/** Undefined fields are unknown; numbers are values the synced data proves, zeros included. */
export interface TaskStats {
  model?: string
  /** Display label of the agent that ran the child. */
  agent?: string
  toolCalls?: number
  fails?: number
  tokens?: { input: number; output: number }
  cost?: number
}

export type TasksInput = {
  scope: ServerScope
  sessionID: string
  sessions: readonly Session[]
  message: Record<string, Message[] | undefined>
  part: Record<string, Part[] | undefined>
  status: Record<string, SessionStatus | undefined>
  permission: Record<string, PermissionRequest[] | undefined>
  question: Record<string, QuestionRequest[] | undefined>
  /** Synced agents, which turn the stable ids in Task calls and messages into labels. */
  agents: readonly { id?: string; name: string }[]
  /** True only after a transcript page has loaded, with no page load in flight. */
  loaded: (sessionID: string) => boolean
  /** True while older transcript pages exist that the store has not loaded. */
  more: (sessionID: string) => boolean
}

/**
 * Derives the background-work list for the current session from the already
 * synced reactive stores — sessions (incl. children via parentID), message
 * parts, session status and pending requests. No fetching, no polling.
 */
export function createTasksData() {
  const sync = useSync()
  const serverSDK = useServerSDK()
  const { params } = useSessionLayout()

  const items = createMemo(() => {
    const sessionID = params.id
    if (!sessionID) return { running: [] as TasksItem[], finished: [] as TasksItem[] }
    const store = sync()
    return deriveTasks({
      scope: serverSDK().scope,
      sessionID,
      sessions: store.data.session ?? [],
      message: store.data.message,
      part: store.data.part,
      status: store.data.session_status,
      permission: store.data.permission,
      question: store.data.question,
      agents: store.data.agent,
      loaded: store.session.history.loaded,
      more: store.session.history.more,
    })
  })

  const liveCount = createMemo(() => items().running.length)

  const ready = () => sync().ready && (!params.id || sync().data.message[params.id] !== undefined)
  return { items, liveCount, ready }
}

/** The one Tasks projection a session owns; every Tasks and Activity view reads this instance. */
export type TasksData = ReturnType<typeof createTasksData>

/**
 * The compact Tasks summary: active work first (needs input, then running; newest known start
 * first, unknown starts after known ones, then by key). Finished work fills only the slots active
 * work leaves free, failures first. Counts come from the whole collection, never from the rows shown.
 * The detail lists every task in the same order, so the summary rows are its head. The side panel shows
 * no counts, so `recent` holds only the 12 newest finished tasks, whatever their outcome.
 */
export function summarizeTasks(items: { running: TasksItem[]; finished: TasksItem[] }, limit = 3) {
  const active = items.running.toSorted(
    (a, b) =>
      Number(b.state === "needs-input") - Number(a.state === "needs-input") ||
      newest(a.startTime, b.startTime) ||
      a.key.localeCompare(b.key),
  )
  const finished = items.finished.toSorted(
    (a, b) =>
      Number(b.state === "error") - Number(a.state === "error") ||
      newest(finishedTime(a), finishedTime(b)) ||
      a.key.localeCompare(b.key),
  )
  const rows = [...active.slice(0, limit), ...finished.slice(0, Math.max(0, limit - active.length))]
  return {
    rows,
    running: active,
    finished,
    recent: items.finished
      .toSorted((a, b) => newest(finishedTime(a), finishedTime(b)) || a.key.localeCompare(b.key))
      .slice(0, 12),
    active: active.length,
    needsInput: active.filter((item) => item.state === "needs-input").length,
    hiddenFailures: finished.filter((item) => item.state === "error" && !rows.includes(item)).length,
    total: active.length + finished.length,
  }
}

/** When a finished task ended. A failure may never record an end (its last message never completed), so its start stands in. */
export function finishedTime(task: TasksItem) {
  if (task.state === "error") return task.endTime ?? task.startTime
  return task.endTime
}

/** Comparator for optional timestamps: newest first, unknown after every known one. */
export function newest(a: number | undefined, b: number | undefined) {
  if (a === undefined) return b === undefined ? 0 : 1
  if (b === undefined) return -1
  return b - a
}

export function deriveTasks(input: TasksInput) {
  const waiting = waitingRequests(input)
  const messages = input.message[input.sessionID] ?? []
  const users = new Set(
    messages
      .filter((message) => message.role === "user" && message.sessionID === input.sessionID)
      .map((message) => message.id),
  )
  const origins = new Map(
    messages.flatMap((message) =>
      message.role === "assistant" && message.sessionID === input.sessionID && users.has(message.parentID)
        ? [[message.id, message.parentID] as const]
        : [],
    ),
  )
  const calls = messages.flatMap((message) =>
    (input.part[message.id] ?? []).filter(
      (part): part is ToolPart =>
        part.type === "tool" && part.sessionID === input.sessionID && part.messageID === message.id,
    ),
  )
  const source = (part: ToolPart | undefined) =>
    part && {
      sourceMessageID: part.messageID,
      sourcePartID: part.id,
      callID: part.callID,
      originUserMessageID: origins.get(part.messageID),
    }
  // The latest task call per child wins: resuming a task reuses its child session.
  const taskCalls = new Map(
    calls.flatMap((part) => {
      const childID = isTaskTool(part.tool) ? text(toolMetadata(part).sessionId) : undefined
      return childID ? [[childID, part] as const] : []
    }),
  )
  const sessions = new Map(input.sessions.map((session) => [session.id, session]))
  const childIDs = new Set([
    ...input.sessions.flatMap((session) => (session.parentID === input.sessionID ? [session.id] : [])),
    ...taskCalls.keys(),
  ])
  const agents = [...childIDs].map((childID) => ({
    ...agentItem(input, waiting, childID, sessions.get(childID), taskCalls.get(childID)),
    ...source(taskCalls.get(childID)),
  }))
  // Foreground shell tools surface as Shell cards while running.
  const shells = new Map(
    calls
      .filter((part) => (part.tool === "bash" || part.tool === "shell") && !terminal(part.state))
      .map((part): [string, TasksItem] => [
        part.callID,
        {
          key: ScopedKey.from(input.scope, input.sessionID, "shell", part.callID),
          kind: "shell",
          headline: toolTitle(part) ?? part.tool,
          state: waiting.calls.has(part.callID) ? "needs-input" : "running",
          startTime: toolStart(part.state),
          sessionId: input.sessionID,
          ...source(part),
        },
      ]),
  )
  const all = [...agents, ...shells.values()]
  return {
    running: all.filter(live).sort((a, b) => (b.startTime ?? 0) - (a.startTime ?? 0)),
    finished: all.filter((item) => !live(item)).sort((a, b) => (b.endTime ?? 0) - (a.endTime ?? 0)),
  }
}

export function live(item: Pick<TasksItem, "state">) {
  return item.state === "running" || item.state === "needs-input"
}

export type StopState = "pending" | "failed"

/**
 * Stop interrupts the child session only — never the parent — and keeps the outcome visible: pending
 * while in flight, failed with retry on rejection. Task keys are server and session qualified, so an
 * outcome that settles after the view moved to another session still lands on its own row.
 */
export function createTaskStops(interrupt: (sessionID: string) => Promise<unknown>) {
  const [stops, setStops] = createStore<Record<string, StopState | undefined>>({})
  return {
    state: (key: string) => stops[key],
    stop(item: TasksItem) {
      const sessionID = item.childId
      if (!sessionID || stops[item.key] === "pending") return
      setStops(item.key, "pending")
      interrupt(sessionID).then(
        () => setStops(item.key, undefined),
        () => setStops(item.key, "failed"),
      )
    },
  }
}

function agentItem(
  input: TasksInput,
  waiting: ReturnType<typeof waitingRequests>,
  childID: string,
  child: Session | undefined,
  call: ToolPart | undefined,
): TasksItem {
  const callInput = call?.state.input ?? {}
  const agentType = taskAgentType(callInput, toolMetadata(call))
  const outcome = agentOutcome(input, waiting, childID, call)
  return {
    key: ScopedKey.from(input.scope, input.sessionID, "agent", childID),
    kind: "agent",
    // Child session titles read "<description> (@<agent> subagent)".
    headline:
      (call && toolTitle(call)) ||
      text(callInput.description) ||
      (child ? (sessionTitle(child.title) ?? "").replace(/ \(@[^)]* subagent\)$/, "") : childID),
    agentID: agentType,
    agent: label(input, agentType),
    state: outcome.state,
    startTime: child?.time.created ?? (call ? toolStart(call.state) : undefined),
    endTime: outcome.endTime,
    childId: childID,
    sessionId: input.sessionID,
    nested: input.sessions.filter((session) => session.parentID === childID).length || undefined,
    stats: agentStats(input, childID, child, call),
  }
}

/** Claims an outcome only from a record that proves it; otherwise "unknown". */
function agentOutcome(
  input: TasksInput,
  waiting: ReturnType<typeof waitingRequests>,
  childID: string,
  call: ToolPart | undefined,
): { state: TasksItemState; endTime?: number } {
  if (waiting.sessions.has(childID) || (call && waiting.calls.has(call.callID))) return { state: "needs-input" }
  if ((input.status[childID]?.type ?? "idle") !== "idle") return { state: "running" }
  // A background task call completes as soon as its job starts, so only the
  // child transcript can prove how the child itself ended.
  if (call && toolMetadata(call).background !== true) {
    if (call.state.status === "completed") return { state: "completed", endTime: call.state.time.end }
    if (call.state.status === "error")
      return { state: interruptedCall(call) ? "interrupted" : "error", endTime: call.state.time.end }
    return { state: "running" }
  }
  const last = input.message[childID]?.at(-1)
  if (last?.role !== "assistant") return { state: "unknown" }
  if (last.error?.name === "MessageAbortedError") return { state: "interrupted", endTime: last.time.completed }
  if (last.error) return { state: "error", endTime: last.time.completed }
  if (last.finish && !["tool-calls", "unknown"].includes(last.finish))
    return { state: "completed", endTime: last.time.completed }
  return { state: "unknown" }
}

function agentStats(
  input: TasksInput,
  childID: string,
  child: Session | undefined,
  call: ToolPart | undefined,
): TaskStats {
  const messages = input.message[childID]
  const last = messages?.findLast((message): message is AssistantMessage => message.role === "assistant")
  const complete = input.loaded(childID) && transcriptComplete(messages, input.part, input.more(childID))
  const assistants = complete
    ? messages.filter((message): message is AssistantMessage => message.role === "assistant")
    : undefined
  const tools = complete
    ? messages.flatMap((message) => (input.part[message.id] ?? []).filter((part) => part.type === "tool"))
    : undefined
  const callModel = toolMetadata(call).model
  const aggregate = child
  return {
    model:
      (last && shortModel(last.providerID, last.modelID)) ??
      (child?.model && shortModel(child.model.providerID, child.model.id)) ??
      (isRecord(callModel) ? shortModel(text(callModel.providerID), text(callModel.modelID)) : undefined),
    agent: label(input, last?.agent || child?.agent || undefined),
    toolCalls: tools?.length,
    fails: tools?.filter((part) => part.state.status === "error").length,
    // Session aggregates are server-maintained; a complete transcript is the only other proof.
    tokens: aggregate?.tokens
      ? { input: aggregate.tokens.input, output: aggregate.tokens.output }
      : assistants && {
          input: assistants.reduce((sum, message) => sum + message.tokens.input, 0),
          output: assistants.reduce((sum, message) => sum + message.tokens.output, 0),
        },
    cost: aggregate?.cost ?? assistants?.reduce((sum, message) => sum + message.cost, 0),
  }
}

/**
 * A loaded transcript proves counts only when no older page remains, every
 * message has parts, and every assistant turn's prompt is present.
 */
function transcriptComplete(
  messages: Message[] | undefined,
  parts: TasksInput["part"],
  more: boolean,
): messages is Message[] {
  if (!messages || more || messages.some((message) => parts[message.id] === undefined)) return false
  const prompts = new Set(messages.flatMap((message) => (message.role === "user" ? [message.id] : [])))
  return prompts.size > 0 && messages.every((message) => message.role === "user" || prompts.has(message.parentID))
}

/** Pending permissions and questions, indexed by owning session and by raising tool call. */
function waitingRequests(input: TasksInput) {
  const requests = [
    ...Object.values(input.permission).flatMap((list) => list ?? []),
    ...Object.values(input.question).flatMap((list) => list ?? []),
  ]
  return {
    sessions: new Set(requests.map((request) => request.sessionID)),
    calls: new Set(requests.flatMap((request) => (request.tool ? [request.tool.callID] : []))),
  }
}

// processor.ts marks parent aborts; task.ts reports a cancelled child as "Task cancelled".
function interruptedCall(call: ToolPart) {
  if (call.state.status !== "error") return false
  return (
    toolMetadata(call).interrupted === true ||
    call.state.error === "Tool execution aborted" ||
    call.state.error === "Task cancelled"
  )
}

function terminal(state: ToolPart["state"]) {
  return state.status === "completed" || state.status === "error"
}

function toolTitle(part: ToolPart) {
  if (part.state.status !== "completed" && part.state.status !== "running") return undefined
  // The V2 projection titles a completed call with the bare tool name, which says nothing about the task.
  if (part.state.title === part.tool) return undefined
  return part.state.title || undefined
}

function toolStart(state: ToolPart["state"]) {
  if (state.status === "pending") return undefined
  return state.time.start
}

function toolMetadata(part: ToolPart | undefined): Record<string, unknown> {
  if (!part) return {}
  if (part.state.status === "pending") return part.metadata ?? {}
  // The V2 projection always sets part metadata (provider state); the tool's own metadata, which carries the child session id, lives on the state.
  return { ...part.state.metadata, ...part.metadata }
}

// Task calls and messages store the agent's stable id; servers that predate ids store the name, which is then the key.
function label(input: TasksInput, id: string | undefined) {
  if (!id) return undefined
  return input.agents.find((agent) => agentKey(agent) === id)?.name ?? id
}

function shortModel(providerID: string | undefined, modelID: string | undefined) {
  if (!providerID || !modelID) return undefined
  return `${providerID}/${modelID.replace(/^(anthropic|openai|google|orchestra)-/i, "")}`
}

function text(value: unknown) {
  return typeof value === "string" && value.length > 0 ? value : undefined
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value)
}
